"""Reading and atomically writing kitty.json."""

import json
import os
import tempfile

from kitty.errors import KittyError

FILENAME = "kitty.json"


def _path(directory: str) -> str:
    return os.path.join(directory, FILENAME)


def exists(directory: str = ".") -> bool:
    return os.path.exists(_path(directory))


def load(directory: str = ".") -> dict:
    path = _path(directory)
    if not os.path.exists(path):
        raise KittyError(f"no {FILENAME} here; run init first")
    try:
        with open(path, encoding="utf-8") as f:
            state = json.load(f)
    except (OSError, UnicodeDecodeError, ValueError) as e:
        raise KittyError(f"cannot read {FILENAME}: {e}") from None
    if not isinstance(state, dict):
        raise KittyError(f"cannot read {FILENAME}: not a kitty file")
    return state


def save(state: dict, directory: str = ".") -> None:
    tmp = tempfile.NamedTemporaryFile(
        "w", encoding="utf-8", dir=directory, prefix=".kitty-", suffix=".tmp", delete=False)
    try:
        with tmp:
            json.dump(state, tmp, indent=2, ensure_ascii=False)
            tmp.write("\n")
        os.replace(tmp.name, _path(directory))
    except OSError as e:
        if os.path.exists(tmp.name):
            os.unlink(tmp.name)
        raise KittyError(f"cannot write {FILENAME}: {e}") from None

