import os
import tempfile
import unittest

from kitty import storage
from kitty.errors import KittyError


class StorageTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.d = self._tmp.name

    def tearDown(self):
        self._tmp.cleanup()

    def _write(self, text):
        with open(os.path.join(self.d, storage.FILENAME), "w") as f:
            f.write(text)

    def test_round_trip(self):
        storage.save({"base": "EUR"}, self.d)
        self.assertEqual(storage.load(self.d), {"base": "EUR"})
        self.assertTrue(storage.exists(self.d))

    def test_load_missing(self):
        self.assertFalse(storage.exists(self.d))
        with self.assertRaises(KittyError):
            storage.load(self.d)

    def test_load_malformed(self):
        for text in ["{not json", "[]", ""]:
            self._write(text)
            with self.assertRaises(KittyError, msg=text):
                storage.load(self.d)

    def test_save_leaves_no_temp_files(self):
        storage.save({"base": "EUR"}, self.d)
        self.assertEqual(os.listdir(self.d), ["kitty.json"])

    def test_save_keeps_normal_permissions(self):
        storage.save({"base": "EUR"}, self.d)
        mode = os.stat(os.path.join(self.d, storage.FILENAME)).st_mode & 0o777
        self.assertEqual(mode & 0o044, 0o044)


if __name__ == "__main__":
    unittest.main()

import unittest
from decimal import Decimal

from kitty.errors import KittyError
from kitty.money import (convert, fmt, parse_amount, parse_currency, parse_date,
                         parse_percent, parse_rate, parse_share, split_equal,
                         split_weighted)


class MoneyTests(unittest.TestCase):
    def test_parse_amount(self):
        self.assertEqual(parse_amount("45"), 4500)
        self.assertEqual(parse_amount("45.5"), 4550)
        self.assertEqual(parse_amount("0.01"), 1)

    def test_parse_amount_errors(self):
        for bad in ["12.345", "0", "0.00", "-5", "abc", ""]:
            with self.assertRaises(KittyError, msg=bad):
                parse_amount(bad)

    def test_parse_amount_rejects_decimal_oddities(self):
        for bad in ["NaN", "Infinity", "1e3", " 5", "+5", "5.", ".5"]:
            with self.assertRaises(KittyError, msg=bad):
                parse_amount(bad)

    def test_parse_currency(self):
        self.assertEqual(parse_currency("usd"), "USD")
        for bad in ["US", "USDX", "U1D", ""]:
            with self.assertRaises(KittyError, msg=bad):
                parse_currency(bad)

    def test_parse_rate(self):
        self.assertEqual(parse_rate("0.92"), Decimal("0.92"))
        self.assertEqual(parse_rate("1.08765"), Decimal("1.08765"))
        for bad in ["0", "-1", "x", "NaN"]:
            with self.assertRaises(KittyError, msg=bad):
                parse_rate(bad)

    def test_parse_percent_and_share(self):
        self.assertEqual(parse_percent("60"), 6000)
        self.assertEqual(parse_percent("33.33"), 3333)
        self.assertEqual(parse_share("2"), 2)
        for bad in ["0", "1.5", "-1", "x"]:
            with self.assertRaises(KittyError, msg=bad):
                parse_share(bad)
        with self.assertRaises(KittyError):
            parse_percent("0")

    def test_parse_date(self):
        self.assertEqual(parse_date("2026-07-14"), "2026-07-14")
        for bad in ["2026-02-30", "2026-7-14", "14/07/2026", "20260714"]:
            with self.assertRaises(KittyError, msg=bad):
                parse_date(bad)

    def test_convert_half_up(self):
        self.assertEqual(convert(4500, Decimal("0.92")), 4140)
        self.assertEqual(convert(1, Decimal("0.5")), 1)
        self.assertEqual(convert(3, Decimal("0.5")), 2)
        self.assertEqual(convert(1, Decimal("0.4")), 0)

    def test_split_equal(self):
        self.assertEqual(split_equal(1000, ["Alice", "Bob", "Cara"]),
                         [("Alice", 334), ("Bob", 333), ("Cara", 333)])

    def test_split_shares(self):
        self.assertEqual(split_weighted(1000, [("A", 1), ("B", 2)]),
                         [("A", 334), ("B", 666)])

    def test_split_leftover_in_list_order(self):
        self.assertEqual(split_weighted(1001, [("B", 1), ("A", 1), ("C", 1)]),
                         [("B", 334), ("A", 334), ("C", 333)])

    def test_split_sum_invariant(self):
        for total in [1, 7, 999, 1000, 12345, 99999]:
            for weights in [[1], [1, 1, 1], [3, 7], [6000, 4000],
                            [3333, 3333, 3334], [1, 2, 3, 4, 5, 6, 7]]:
                parts = split_weighted(total, [(str(i), w) for i, w in enumerate(weights)])
                self.assertEqual(sum(c for _, c in parts), total)

    def test_fmt(self):
        self.assertEqual(fmt(4140), "41.40")
        self.assertEqual(fmt(-2070), "-20.70")
        self.assertEqual(fmt(-5), "-0.05")
        self.assertEqual(fmt(0), "0.00")


if __name__ == "__main__":
    unittest.main()

